<template>
 <main class="lift-console" v-if="msg?.payload?.state">
  <header class="lift-header"><div><span class="eyebrow">EE-2401 · INDUSTRIAL AUTOMATION</span><h1>Three floor elevator</h1><p>Izbassar Yesbol · Kuanysh Kali</p></div><div class="sim-label"><span class="live-dot"></span>{{s.connection.live?'TRILOGI CONNECTED':'PLC DISCONNECTED'}}<span>Native ladder · MQTT · Simulated field</span></div></header>
  <div class="alarm-line" :class="{danger:s.alarms.length||!s.connection.live}"><span>{{!s.connection.live?'No fresh PLC telemetry — controls blocked':s.alarms.length ? s.alarms.join(' · ') : 'Live native ladder · all monitored conditions normal'}}</span><strong>{{s.state}}</strong></div>
  <div class="lift-layout">
   <section class="shaft-panel"><div class="panel-heading"><h2>Cabin overview</h2><span>{{s.outputs.MOTOR_UP?'↑ UP':s.outputs.MOTOR_DOWN?'↓ DOWN':'STATIONARY'}}</span></div>
    <div class="shaft-scene">
     <div class="floor-row" v-for="f in [3,2,1]" :key="f" :style="{bottom:(f-1)*35+6+'%'}"><span class="floor-label">0{{f}}</span><span class="landing" :class="{requested:s.requests.includes(f)}"></span><button :aria-label="'Call floor '+f" :class="{queued:s.requests.includes(f)}" @click="call(f)" :disabled="!s.run">{{s.requests.includes(f)?'●':'CALL'}}</button></div>
     <div class="shaft-rails"></div>
     <div class="cabin" :style="{bottom:((s.position-1)*35+5)+'%'}"><div class="cabin-top">{{s.currentFloor || '—'}}</div><div class="door-space"><div class="door-leaf left" :style="{transform:'translateX('+(-s.door*100)+'%)'}"></div><div class="door-leaf right" :style="{transform:'translateX('+(s.door*100)+'%)'}"></div><span class="inside-label">LIFT</span></div><div class="cabin-foot"></div></div>
    </div><p class="shaft-caption">{{s.currentFloor?'Confirmed at floor '+s.currentFloor:'Between floors · last confirmed '+(s.lastFloor||'unknown')}} · Door {{Math.round(s.door*100)}}% open</p>
   </section>
   <section class="controls-panel"><div class="panel-heading"><h2>Operator controls</h2><span :class="{ready:s.run}">{{s.run?'ENABLED':'DISABLED'}}</span></div>
    <div class="metrics"><div><small>CONFIRMED FLOOR</small><strong>{{s.currentFloor || '—'}}</strong></div><div><small>DOOR FEEDBACK</small><strong class="word">{{s.inputs.DOOR_OPEN?'OPEN':s.inputs.DOOR_CLOSED?'CLOSED':'IN TRANSIT'}}</strong></div><div><small>PENDING STOPS</small><strong class="word">{{s.requests.join(' · ')||'NONE'}}</strong></div></div>
    <p class="control-label">CABIN DESTINATION</p><div class="destination-row"><button v-for="f in [1,2,3]" :key="f" :class="{queued:s.requests.includes(f)}" :aria-label="'Destination '+f" @click="call(f)" :disabled="!s.run">{{f}}<small>{{s.requests.includes(f)?'QUEUED':'FLOOR'}}</small></button></div>
    <div class="action-row"><button class="start" @click="cmd('start')" :disabled="s.alarms.length>0||!s.connection.live">Start</button><button @click="cmd('reset')" :disabled="!s.connection.live">Reset alarm</button><button class="emergency" @click="cmd('estop')">{{s.flags.estop?'Release E-stop':'Emergency stop'}}</button></div>
    <p class="control-help">Reset clears a corrected fault. Press Start separately to resume. Travel requires confirmed closed doors.</p>
    <div class="output-strip"><span v-for="(on,k) in s.outputs" :key="k" :class="{on}"><i></i>{{k}}</span></div>
    <details class="fault-tools"><summary>Simulation and fault controls</summary><div class="fault-grid"><button v-for="item in faults" :key="item.key" :class="{faultActive:s.flags[item.key]}" @click="cmd(item.key)">{{item.label}} {{s.flags[item.key]?'ON':'OFF'}}</button></div><div class="action-row"><button @click="cmd('pause',{value:s.flags.paused})">{{s.flags.paused?'Resume field model':'Pause field model'}}</button><button @click="cmd('new-demo')">Restore field to floor 1</button></div><p>Field mechanics are simulated. All control states and outputs come from the running TriLOGI ladder. Restoring the field does not clear PLC faults: use Reset, then Start.</p></details>
   </section>
  </div>
  <section class="event-panel"><div class="panel-heading"><h2>Event history</h2><span>FIELD TIME {{s.time}} s · PLC TX {{s.connection.tx}} / RX {{s.connection.rx}} · {{s.connection.ageMs??'—'}} ms</span></div><div class="event-grid"><div v-for="(e,i) in s.log.slice(0,6)" :key="i"><time>{{e.time}} s</time><span>{{e.event}}</span></div></div></section>
 </main><div v-else class="waiting-screen">Waiting for the simulation model…</div>
</template>
<script>
export default {computed:{s(){return this.msg.payload}},data(){return{faults:[{key:'obstruction',label:'Door obstruction'},{key:'jam',label:'Door closing jam'},{key:'driveFault',label:'Drive stopped'},{key:'conflict',label:'Floor sensor conflict'},{key:'lostDoor',label:'Closed sensor lost'}]}},methods:{cmd(action,extra={}){this.send({topic:'command',payload:{action,...extra}})},call(floor){this.cmd('call',{floor})}}}
</script>
<style>
