a}.lift-console button{cursor:pointer;background:#253951;border:1px solid #405570;color:var(--ink);padding:10px 15px;border-radius:5px;font:inherit;font-size:12px}.floor-row button{font-size:10px;width:61px;padding:9px 3px}.lift-console button:hover{filter:brightness(1.2)}.lift-console button:disabled{opacity:.45;cursor:default}.lift-console button.queued{background:#845f24;border-color:#dfb35f;color:#fff1cb}.cabin{position:absolute;left:28%;width:37%;height:84px;background:#7d9cb8;border:2px solid #b2c8db;border-radius:4px;z-index:3;transition:bottom .1s linear;box-shadow:0 7px 20px #0005}.cabin-top{height:19px;text-align:center;background:#18342f;color:var(--green);font-size:12px}.door-space{position:relative;height:56px;margin:2px 8px;background:#24344a;overflow:hidden}.door-leaf{position:absolute;top:0;bottom:0;width:50%;background:linear-gradient(90deg,#59748d,#a5bcd0);z-index:2;transition:transform .1s linear}.door-leaf.left{left:0;border-right:1px solid #253951}.door-leaf.right{right:0;border-left:1px solid #253951}.inside-label{position:absolute;left:0;right:0;top:20px;text-align:center;font-size:10px;letter-spacing:3px;color:#7d9cb8}.shaft-caption{color:var(--muted);font-size:11px;margin-top:21px}.metrics{display:grid;grid-template-columns:.8fr 1.2fr 1fr;gap:10px;margin:24px 0}.metrics>div{border-bottom:1px solid var(--line);padding-bottom:17px}.metrics small{display:block;font-size:9px;letter-spacing:1px;color:var(--muted);margin-bottom:13px}.metrics strong{font-size:34px;font-weight:500}.metrics strong.word{font-size:17px;display:block;padding-top:10px}.control-label{font-size:10px;letter-spacing:1px;color:var(--muted);margin:22px 0 13px}.destination-row{display:flex;gap:13px}.destination-row button{flex:1;font-size:27px;padding:12px}.destination-row button small{display:block;font-size:8px;letter-spacing:1px;margin-top:5px}.action-row{display:flex;gap:10px;margin-top:20px}.action-row button{flex:1}.action-row .start{background:#226c51;border-color:#398c6c}.action-row .emergency{background:#873641;border-color:#b25460}.control-help{font-size:11px;line-height:1.6;color:var(--muted);margin:14px 0}.output-strip{display:flex;flex-wrap:wrap;gap:10px;font-size:8px;color:var(--muted);padding:13px 0;border-top:1px solid var(--line);border-bottom:1px solid var(--line)}.output-strip i{display:inline-block;width:6px;height:6px;background:#42516a;border-radius:50%;margin-right:5px}.output-strip .on{color:var(--green)}.output-strip .on i{background:var(--green)}.fault-tools{margin-top:17px;font-size:11px;color:var(--muted)}.fault-tools summary{cursor:pointer}.fault-grid{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:15px}.fault-grid button{font-size:10px}.fault-grid .faultActive{background:#873641;border-color:#b25460}.fault-tools p{line-height:1.5;margin-top:12px}.event-panel{margin-top:24px}.event-grid{display:grid;grid-template-columns:1fr 1fr 1fr;gap:10px;margin-top:16px}.event-grid>div{display:flex;gap:12px;font-size:10px}.event-grid time{color:var(--green);white-space:nowrap}.event-grid span{color:var(--muted)}.waiting-screen{padding:30px}.v-main{background:#0b1422!important}.v-card{background:transparent!important}.nrdb-ui-group{border:0!important;background:transparent!important}@media(max-width:850px){.lift-layout{grid-template-columns:1fr}.lift-console{padding:20px}.lift-header h1{font-size:25px}.sim-label{display:none}.event-grid{grid-template-columns:1fr 1fr}.alarm-line{flex-direction:column}}
